"use strict";(self.webpackChunkevmcrispr_doc=self.webpackChunkevmcrispr_doc||[]).push([[1165],{4402:function(e){e.exports=JSON.parse('{"pluginId":"aragonOS","version":"current","label":"Next","banner":null,"badge":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"aragonOS":[{"type":"link","label":"Introduction to Aragon DAOs","href":"/evmcrispr-doc/aragonOS/","docId":"aragonOSintro"},{"type":"category","label":"Aragon Apps","items":[{"type":"link","label":"Token Manager","href":"/evmcrispr-doc/aragonOS/token-manager","docId":"token-manager"},{"type":"link","label":"Voting","href":"/evmcrispr-doc/aragonOS/voting","docId":"voting"},{"type":"link","label":"Finance","href":"/evmcrispr-doc/aragonOS/finance","docId":"finance"},{"type":"link","label":"Vault","href":"/evmcrispr-doc/aragonOS/vault","docId":"vault"},{"type":"link","label":"Agent","href":"/evmcrispr-doc/aragonOS/agent","docId":"agent"},{"type":"link","label":"Vote Aggregator","href":"/evmcrispr-doc/aragonOS/vote-aggregator","docId":"vote-aggregator"},{"type":"link","label":"Token Wrapper","href":"/evmcrispr-doc/aragonOS/token-wrapper","docId":"token-wrapper"},{"type":"link","label":"Transactions","href":"/evmcrispr-doc/aragonOS/transactions","docId":"transactions"}],"collapsed":true,"collapsible":true},{"type":"category","label":"Gardens Apps","items":[{"type":"link","label":"Disputable Voting","href":"/evmcrispr-doc/aragonOS/disputableVoting","docId":"disputableVoting"},{"type":"link","label":"Conviction Voting","href":"/evmcrispr-doc/aragonOS/convictionVoting","docId":"convictionVoting"},{"type":"link","label":"Agreement","href":"/evmcrispr-doc/aragonOS/agreement","docId":"agreement"}],"collapsed":true,"collapsible":true}]},"docs":{"agent":{"id":"agent","title":"Agent","description":"The Agent App executes interactions with external Ethereum addresses, including smart contracts. Along with the Vault contract, the Agent can also hold its own Treasury, which a Finance App can manage. Multiple Agents can be helpful for various reasons, such as maintaining numerous treasuries or scoping permissions to external smart contracts related to your DAO or protocol (by making the Agent an owner or admin).","sidebar":"aragonOS"},"agreement":{"id":"agreement","title":"Agreement","description":"The agreement app defines and manages an agreement or set of rules that participants of your DAO should adhere to. This contract also manages settling or escalating potential infractions of the aforementioned DAO agreement. It has no UI and is usually interacted with by an instance of Gardens, which is developed by 1Hive.","sidebar":"aragonOS"},"aragonOSintro":{"id":"aragonOSintro","title":"Introduction to Aragon DAOs","description":"AragonOS is the main framework that EVMcrispr has been tailored to interact with. Aragon DAOs are easily deployable and highly customizable governance platforms that can be launched using the Aragon Client on Mainnet or on Gnosis Chain via 1hive\'s Aragon Deployment.","sidebar":"aragonOS"},"convictionVoting":{"id":"convictionVoting","title":"Conviction Voting","description":"Conviction Voting is an app developed by 1Hive. It has no UI and should be accessed by a deployed instance of Gardens. Gardens is a tool for DAOs that utilizes Aragon OS with a custom UI on top. Learn more about Conviction Voting in the Gardens Documentation.","sidebar":"aragonOS"},"disputableVoting":{"id":"disputableVoting","title":"Disputable Voting","description":"Disputable Voting (also referred to as Tao Voting or Decision Voting) is an app developed initially by Aragon One and maintained by 1Hive. It has no UI and should be accessed by a deployed instance of Gardens. Gardens is a tool for DAOs that utilizes AragonOS with a custom UI on top. Learn more about Disputable Voting in the Gardens Documentation.","sidebar":"aragonOS"},"finance":{"id":"finance","title":"Finance","description":"The Finance App will allow you to keep track of your DAO\'s finances, and each app can only interact with funds held in one Ethereum Address. Having multiple Finance Apps will allow you to manage various treasuries.","sidebar":"aragonOS"},"install":{"id":"install","title":"install","description":"The install command will install a native or custom aragon app to your DAO. In this article we will breakdown the parameters and how to install native Aragon OS apps. These include"},"token-manager":{"id":"token-manager","title":"Token Manager","description":"The Token Manager app, as the name implies, is for managing tokens. Usually, this app is complemented by a unique token contract for each instance of the Token Manager app.","sidebar":"aragonOS"},"token-wrapper":{"id":"token-wrapper","title":"Token Wrapper","description":"This app will enable you to convert a regular ERC20 token into a checkpointed ERC20 token, thus making it compatible with the Voting App, Disputable Voting App, and Vote Aggregator App.","sidebar":"aragonOS"},"transactions":{"id":"transactions","title":"Transactions","description":"The Transactions app is a custom Aragon app built by 1Hive. It allows users to create a single DAO vote to transfer or mint tokens to multiple addresses.","sidebar":"aragonOS"},"vault":{"id":"vault","title":"Vault","description":"The Vault is a simple app intended to store funds. It doesn\'t have a user interface, so it is typically installed in tandem with the Finance app to manage the funds inside of it.","sidebar":"aragonOS"},"vote-aggregator":{"id":"vote-aggregator","title":"Vote Aggregator","description":"This Aragon App can aggregate the voting weight from multiple sources (checkpointed ERC20 tokens and ERC900 staking contracts) into a single voting token. It has no UI and can only be manipulated directly from the smart contract or using EVMcrispr. For ERC20 tokens without checkpointing, you can use the Token Wrapper app to wrap them into a compatible token type.","sidebar":"aragonOS"},"voting":{"id":"voting","title":"Voting","description":"The Voting App will allow your DAO members to create votes that will usually execute internal DAO actions or external interactions with other Ethereum Addresses, including smart contracts.","sidebar":"aragonOS"}}}')}}]);